const D = { energy: .6, scale: 1, density: .5, speed: 1, wind: .55, hue: 210, x: .5, y: .32, style: 'weathered', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Lines of Tibetan lung-ta prayer flags strung between poles, the cloth fluttering so a
// wind wave travels the row and the free edges ripple. A SET: it spans a diagonal band and
// leaves the rest of the frame open; alpha scales every mark. New family. ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, en = cl(P.energy,0,1), dn = cl(P.density,0,1), wnd = cl(P.wind,0,1);
const HU = ((P.hue%360)+360)%360, tt = K.t;
const ink = sty==='ink', bp = sty==='blueprint', riso = sty==='riso', vivid = sty==='vivid';
const AL = cl(P.alpha,0,100);
if (AL > 0.5) {

const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);
const light = (.5+.5*en)*(.55+.5*K.intensity) + bass*.2;
// the five lung-ta colours (sky/air/fire/water/earth): [h,s,b]
const baseCols = [[210,70,66],[0,0,94],[2,72,66],[135,58,50],[46,80,74]];
function fcol(idx){
  let c = baseCols[idx%5].slice();
  if (sty==='weathered'){ c[1]*=0.55; c[2]=cl(c[2]*0.82+8,0,96); }
  else if (riso){ c = (idx%2? [4,66,64]:[210,60,60]); }
  else if (!vivid){ c[1]*=0.82; }
  // shift toward the hue param a touch so it's steerable
  c[0] = (c[0] + (HU-210)*0.25 + 360)%360;
  return c;
}

const cx = cl(P.x,.05,.95)*width, cy = cl(P.y,.06,.72)*height;
const fh = u*.075*cl(P.scale,.3,2.4), fw = fh*0.86;      // flag height / width
const nLine = 2 + Math.round(dn*3);
const perLine = 6 + Math.round(dn*7);
const NS = 5;                                            // cloth strips per flag

push();
for (let L=0;L<nLine;L++){
  const ph = fr(L*7.3)*6.28;
  const yc = cy + (L-(nLine-1)/2)*fh*1.7;
  // a diagonal droop line with catenary sag; both ends drift a little on the wind
  const dir = (L%2? 1:-1) * (0.10 + 0.16*fr(L*4.1));
  const swayA = (u*.02+u*.045*wnd)*(.7*Math.sin(tt*.21*P.speed+ph)+.4*Math.sin(tt*.37*P.speed+ph*1.6));
  const x0 = cx - width*.62 + swayA*.4, x1 = cx + width*.62 + swayA*.4;
  const y0 = yc - height*dir + (fr(L*3.7)-.5)*fh, y1 = yc + height*dir + (fr(L*9.1)-.5)*fh;
  const sag = u*.05 + u*.06*wnd + u*.04*Math.sin(tt*.17*P.speed+ph);
  const wireAt = q => [x0+(x1-x0)*q, y0+(y1-y0)*q + sag*4*q*(1-q)];
  // ---- the wire ----
  if (!ink){ noFill(); stroke(bp?200:HU, bp?30:8, bp?100:44, 24*AL/100); strokeWeight(Math.max(1,u*.0011));
    beginShape(); for(let k=0;k<=24;k++){ const w=wireAt(k/24); vertex(w[0],w[1]); } endShape(); }
  // ---- the flags ----
  for (let n=0;n<perLine;n++){
    const q=(n+.6)/(perLine+.2); const w=wireAt(q); const wx=w[0], wy=w[1];
    const fph = q*5.0 + ph + L*1.3;
    const col = fcol(n + L);
    // per-flag wind flutter: horizontal displacement grows toward the free bottom edge
    const amp = fh*(0.12+0.5*wnd);
    const disp = v => amp*(Math.sin(tt*(1.1+.1*L)*P.speed + fph + v*3.2) + .45*Math.sin(tt*1.9*P.speed + fph + v*5.1));
    const bleach = sty==='weathered' ? (0.7+0.3*fr(n*3.1+L*7.7)) : 1;
    // cloth strips, each shaded by the local fold (derivative of disp)
    for (let s2=0;s2<NS;s2++){
      const v0=s2/NS, v1=(s2+1)/NS, vm=(v0+v1)*.5;
      const d0=disp(v0), d1=disp(v1);
      const fold = (d1-d0)/(fh/NS);                        // slope of the cloth -> fold shading
      const shade = cl(.6 + fold*1.2 + light*.15, .28, 1.15);
      // width foreshortens where the cloth turns away from us
      const narrow = 0.82 + 0.18*Math.cos(fold*2.4);
      const xl0=wx - fw*.5*narrow + d0, xr0=wx + fw*.5*narrow + d0;
      const xl1=wx - fw*.5*narrow + d1, xr1=wx + fw*.5*narrow + d1;
      const yy0=wy + v0*fh, yy1=wy + v1*fh;
      if (bp){
        noFill(); stroke(196,60,100,70*AL/100); strokeWeight(Math.max(1,u*.0013));
        beginShape(); vertex(xl0,yy0);vertex(xr0,yy0);vertex(xr1,yy1);vertex(xl1,yy1); endShape(CLOSE);
      } else if (ink){
        noStroke(); fill(HU,10,10+s2*1.5, cl(90*shade,0,96)*AL/100);
        beginShape(); vertex(xl0,yy0);vertex(xr0,yy0);vertex(xr1,yy1);vertex(xl1,yy1); endShape(CLOSE);
      } else {
        noStroke();
        fill(col[0], col[1]*(riso?1:1), cl(col[2]*shade*bleach,4,98), (riso?84:88)*AL/100);
        beginShape(); vertex(xl0,yy0);vertex(xr0,yy0);vertex(xr1,yy1);vertex(xl1,yy1); endShape(CLOSE);
        // faint woodblock mantra row (a horizontal print band) — texture, not flat fill
        if (!riso){ stroke(col[0],col[1]*.5,cl(col[2]*shade*.55,2,80), 30*AL/100); strokeWeight(Math.max(1,u*.0008));
          const my=(yy0+yy1)*.5; line((xl0+xl1)*.5+fw*.12, my, (xr0+xr1)*.5-fw*.12, my); }
      }
    }
    // frayed bottom edge (a few threads)
    if (!bp && !ink){ stroke(col[0],col[1]*.6,cl(col[2]*.5,2,70), 40*AL/100); strokeWeight(Math.max(1,u*.0007));
      const yb=wy+fh; for(let tfr=0;tfr<4;tfr++){ const fx=wx-fw*.4+fw*.27*tfr+disp(1);
        line(fx,yb, fx+(fr(tfr+n)-.5)*fw*.1, yb+fh*.12*(0.5+fr(tfr*3))); } }
  }
}
pop();
blendMode(BLEND); noTint(); drawingContext.shadowBlur=0; strokeWeight(1);
}
